/* /* */
// C++ section: Rust sees this as inside a nested block comment.
#include <cstdio>
#include <cstdlib>
#include <vector>

int main(int argc, char **argv) {
    long n = argc > 1 ? std::atol(argv[1]) : 0;
    // Big integers stored little-endian in base 1e9.
    std::vector<unsigned long long> a{1}, b{1};
    const unsigned long long BASE = 1000000000ULL;
    for (long i = 0; i < n; i++) {
        std::vector<unsigned long long> c(b.size() + 1, 0);
        unsigned long long carry = 0;
        for (size_t j = 0; j < b.size(); j++) {
            unsigned long long s = b[j] + (j < a.size() ? a[j] : 0) + carry;
            c[j] = s % BASE;
            carry = s / BASE;
        }
        if (carry) c[b.size()] = carry; else c.pop_back();
        a = b;
        b = c;
    }
    std::printf("%llu", a.back());
    for (size_t j = a.size() - 1; j-- > 0;) std::printf("%09llu", a[j]);
    std::printf("\n");
    return 0;
}
// */
//\
fn main() { //\
    let n: u64 = std::env::args().nth(1).and_then(|s| s.trim().parse().ok()).unwrap_or(0); //\
    const BASE: u64 = 1_000_000_000; //\
    let mut a: Vec<u64> = vec![1]; //\
    let mut b: Vec<u64> = vec![1]; //\
    for _ in 0..n { //\
        let mut c: Vec<u64> = Vec::with_capacity(b.len() + 1); //\
        let mut carry = 0u64; //\
        for j in 0..b.len() { //\
            let s = b[j] + if j < a.len() { a[j] } else { 0 } + carry; //\
            c.push(s % BASE); //\
            carry = s / BASE; //\
        } //\
        if carry > 0 { c.push(carry); } //\
        a = b; //\
        b = c; //\
    } //\
    let mut out = format!("{}", a[a.len() - 1]); //\
    for j in (0..a.len() - 1).rev() { out.push_str(&format!("{:09}", a[j])); } //\
    println!("{}", out); //\
}
